inline void OrderLine::attachRuntimeStateRecursive(const EntityRuntimeState& target) {
    root.attach_runtime_state(target);
    if (order_) {
        order_->attachRuntimeStateRecursive(target);
    }
    if (product_) {
        product_->attachRuntimeStateRecursive(target);
    }
}

